omString($currentTimeDb,'Europe/London',true);		$jobs = craft()->db->createCommand()			->select('*')			->from('mailer_scheduler')			->where('dateToSend1 <= :now', array(':now' => $currentTimeDb))			->order('dateToSend')			->queryAll();		$jobs = Mailer_SchedulerModel::populateModels($jobs);		foreach ($jobs as $job) {			$jobPostData = unserialize($job->postData);			$postData = array(							'action'					=> 'mailer/form/send',							'mailer_subject'			=> $job->subject,							'mailer_htmlBody'			=> $job->htmlBody,							'mailer_sendto_custom'		=> $jobPostData['mailer_sendto_custom'],							'mailer_to'					=> $jobPostData['mailer_to'],							'mailer_cc'					=> $jobPostData['mailer_cc'],							'mailer_bcc'				=> $jobPostData['mailer_bcc'],							'mailer_sendto_usergroups'	=> $jobPostData['mailer_sendto_usergroups'],							'mailer_usergroups'			=> $jobPostData['mailer_usergroups'],							'mailer_sendto_users'		=> $jobPostData['mailer_sendto_users'],							'mailer_usergroups'			=> $jobPostData['mailer_usergroups'],							'mailer_sender_name'		=> $jobPostData['mailer_sender_name'],							'mailer_sender_mail'		=> $jobPostData['mailer_sender_mail'],							'mailer_schedule_note'		=> '',							'mailer_schedule_date'		=> array('date'=>''),							'mailer_schedule_time'		=> array('time'=>''),						);			$_POST = $postData;			echo "<PRE>";			print_r($_POST);			echo "</pre><BR><BR>";			// $this->actionSend($postData);		}			}}